-- =====================================================
-- CREATE REMAINING TABLES (Part 2)
-- =====================================================

-- SECUserModule (user permissions per module)
CREATE TABLE "SECUserModule" (
  "UserModuleId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserId" INTEGER REFERENCES "SECUsers"("UserId"),
  "ModuleId" INTEGER REFERENCES "SECModule"("ModuleId"),
  "RoleId" INTEGER REFERENCES "SECRole"("RoleId"),
  "CanView" BOOLEAN DEFAULT FALSE,
  "CanAdd" BOOLEAN DEFAULT FALSE,
  "CanEdit" BOOLEAN DEFAULT FALSE,
  "CanDelete" BOOLEAN DEFAULT FALSE,
  "CanApprove" BOOLEAN DEFAULT FALSE,
  "CanPrint" BOOLEAN DEFAULT FALSE,
  "CanExport" BOOLEAN DEFAULT FALSE,
  "CanImport" BOOLEAN DEFAULT FALSE,
  "CanSubmit" BOOLEAN DEFAULT FALSE,
  "CanProcess" BOOLEAN DEFAULT FALSE,
  "CanGenerate" BOOLEAN DEFAULT FALSE,
  "CanPay" BOOLEAN DEFAULT FALSE,
  "InsertedBy" INTEGER,
  "InsertedOn" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  "InsertedMachineInfo" VARCHAR(255),
  "UpdatedBy" INTEGER,
  "UpdatedOn" TIMESTAMP WITH TIME ZONE,
  "UpdatedMachineInfo" VARCHAR(255),
  "IsActive" BOOLEAN DEFAULT TRUE,
  "Deletable" BOOLEAN DEFAULT TRUE,
  "Custom1" VARCHAR(255),
  "Custom2" VARCHAR(255),
  "Custom3" VARCHAR(255)
);

-- UserPermission
CREATE TABLE "UserPermission" (
  "PermissionId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserId" INTEGER REFERENCES "SECUsers"("UserId"),
  "ModuleId" INTEGER,
  "PermissionType" VARCHAR(50),
  "IsActive" BOOLEAN DEFAULT TRUE
);

-- SecurityQuestionAnswer
CREATE TABLE "SecurityQuestionAnswer" (
  "SQAID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserId" INTEGER REFERENCES "SECUsers"("UserId"),
  "Question1" TEXT,
  "Answer1" VARCHAR(255),
  "Question2" TEXT,
  "Answer2" VARCHAR(255),
  "Question3" TEXT,
  "Answer3" VARCHAR(255),
  "InsertedBy" INTEGER,
  "InsertedOn" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  "InsertedMachineInfo" VARCHAR(255),
  "UpdatedBy" INTEGER,
  "UpdatedOn" TIMESTAMP WITH TIME ZONE,
  "UpdatedMachineInfo" VARCHAR(255),
  "IsActive" BOOLEAN DEFAULT TRUE,
  "Deletable" BOOLEAN DEFAULT TRUE,
  "IsMigrated" BOOLEAN DEFAULT FALSE
);

-- UserOtp
CREATE TABLE "UserOtp" (
  "OtpId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserId" INTEGER REFERENCES "SECUsers"("UserId"),
  "OtpCode" VARCHAR(10),
  "ExpiresAt" TIMESTAMP WITH TIME ZONE,
  "IsUsed" BOOLEAN DEFAULT FALSE,
  "CreatedAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

